// App.js
import React, { useState } from 'react';
import Navbar from './components/Navbar';
import TopBar from './components/TopBar';
import Table from './components/Table';
import SheetRuleCreator from './components/SheetRuleCreator'; // Import the SheetRuleCreator
import './styles/navbar.css'; // Assuming your navbar styles are here

const App = () => {
  const [heading, setHeading] = useState('Home'); // Default heading for the home view
  // currentView can be 'home', 'table', or 'sheetRuleCreator'
  const [currentView, setCurrentView] = useState('home');
  // Stores the data of the row being edited, passed to SheetRuleCreator
  const [editingRowData, setEditingRowData] = useState(null);

  // Handles the "Back" button click in TopBar
  const handleBack = () => {
    console.log('Back button clicked');
    // If currently editing a rule, go back to the table view
    if (currentView === 'sheetRuleCreator') {
      setCurrentView('table');
      setEditingRowData(null); // Clear editing data when going back
      setHeading('Sheet Rule Table'); // Change heading back to table view
    } else {
      // Otherwise, go back to the home view
      setCurrentView('home');
      setHeading('Home'); // Change heading for home view
    }
  };

  // Handles the "Close" button click in TopBar
  const handleClose = () => {
    console.log('Close button clicked');
    // Always go to the home view and clear any editing data
    setCurrentView('home');
    setEditingRowData(null);
    setHeading('Home'); // Reset heading for home view
  };

  // Function passed to Navbar to display the table
  const handleShowTable = () => {
    setCurrentView('table');
    setHeading('Sheet Rule Table'); // Update heading for table view
  };

  // Function passed to Table when an "Edit" button is clicked
  const handleEditRule = (rowData) => {
    setEditingRowData(rowData); // Store the data of the row to be edited
    setCurrentView('sheetRuleCreator'); // Switch to the SheetRuleCreator view
    setHeading(`Edit: ${rowData.name}`); // Set heading to indicate editing specific rule
  };

  return (
    <div style={{ display: 'flex', height: '100vh', fontFamily: 'Inter, sans-serif' }}>
      {/* Navbar component */}
      <Navbar setHeading={setHeading} setShowTable={handleShowTable} />

      <div style={{ display: 'flex', flexDirection: 'column', flex: 1, backgroundColor: '#f0f2f5' }}>
        {/* TopBar component */}
        <TopBar heading={heading} onBack={handleBack} onClose={handleClose} />

        {/* Conditionally render content based on currentView */}
        {currentView === 'home' && (
          <div style={{ flex: 1, padding: '20px', display: 'flex', justifyContent: 'center', alignItems: 'center', flexDirection: 'column' }}>
            <h1 style={{ color: '#333', fontSize: '2.5em', marginBottom: '10px' }}>Hello! 🌟</h1>
            <p style={{ color: '#555', fontSize: '1.2em', marginBottom: '5px' }}>Welcome to STA-UI 🚀</p>
            <p style={{ color: '#777', fontSize: '1em', textAlign: 'center', maxWidth: '600px' }}>
              This is a simple React application to demonstrate the dynamic display of components.
              Use the navigation to explore!
            </p>
          </div>
        )}

        {currentView === 'table' && (
          // Render Table component, passing the handleEditRule function as a prop
          <Table onEdit={handleEditRule} />
        )}

        {currentView === 'sheetRuleCreator' && (
          // Render SheetRuleCreator, passing the editingRowData to pre-fill the form
          <SheetRuleCreator initialData={editingRowData} />
        )}
      </div>
    </div>
  );
};

export default App;
